exercise.starterCode:
int gcd(int a, int b) {
    // 辗转相除
    return 0;
}

exercise.solution:
int gcd(int a, int b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

