int main() {
    int a[5] = {3, 9, 2, 7, 5};
    int n = sizeof(a) / sizeof(a[0]);
    int best = a[0];

    for (int i = 1; i < n; i++) {
        if (a[i] > best) best = a[i];
    }
    printf("n=%d best=%d\n", n, best);

    for (int i = 0; i < n / 2; i++) {
        int t = a[i];
        a[i] = a[n - 1 - i];
        a[n - 1 - i] = t;
    }
    printf("%d %d %d\n", a[0], a[1], a[4]);
    return 0;
}

