exercise.starterCode:
int count_lower(char *s) {
    // 用 isalpha 不够，要判断小写范围
    return 0;
}

exercise.solution:
int count_lower(char *s) {
    int count = 0;
    while (*s != 0) {
        if (*s >= 'a' && *s <= 'z') count++;
        s++;
    }
    return count;
}

